// n8n Code Node: SEARCH - Search alliance and corporation names/tickers in Redis
// v3.0 - Replaced ESI corp search with Redis index search
const Redis = require('ioredis');

const inputData = $input.first().json;
const query = (inputData.query?.q || '').trim().toLowerCase();
const multiMode = inputData.query?.multi === 'true';

if (query.length < 2) {
    return [{ json: { error: "Query too short (min 2 chars)" } }];
}

const redis = new Redis({
    host: 'redis',
    port: 6379,
    db: 0,
    connectTimeout: 5000,
    maxRetriesPerRequest: 2
});

// Helper to fetch ticker from ESI
async function fetchTickerFromESI(id, type = 'alliance') {
    try {
        const endpoint = type === 'corporation' ? 'corporations' : 'alliances';
        const res = await fetch(`https://esi.evetech.net/latest/${endpoint}/${id}/`);
        if (res.ok) {
            const data = await res.json();
            return data.ticker || null;
        }
    } catch (e) { /* ignore */ }
    return null;
}

try {
    // Alliance Redis Keys
    const ALLIANCE_NAME_TO_ID_KEY = 'eve:alliance:name_to_id';
    const ALLIANCE_ID_TO_NAME_KEY = 'eve:alliance:id_to_name';
    const ALLIANCE_TICKER_TO_ID_KEY = 'eve:alliance:ticker_to_id';
    const ALLIANCE_ID_TO_TICKER_KEY = 'eve:alliance:id_to_ticker';
    const ALLIANCE_STATS_KEY = 'intel:stats:alliance:';

    // Corporation Redis Keys (NEW)
    const CORP_NAME_TO_ID_KEY = 'eve:corporation:name_to_id';
    const CORP_ID_TO_NAME_KEY = 'eve:corporation:id_to_name';
    const CORP_TICKER_TO_ID_KEY = 'eve:corporation:ticker_to_id';
    const CORP_ID_TO_TICKER_KEY = 'eve:corporation:id_to_ticker';
    const CORP_STATS_KEY = 'intel:stats:corporation:';

    // Fetch alliance and corporation indexes in parallel
    const [allNames, allTickers, corpNames, corpTickers] = await Promise.all([
        redis.hgetall(ALLIANCE_NAME_TO_ID_KEY),
        redis.hgetall(ALLIANCE_TICKER_TO_ID_KEY),
        redis.hgetall(CORP_NAME_TO_ID_KEY),
        redis.hgetall(CORP_TICKER_TO_ID_KEY)
    ]);

    const matchesMap = new Map();

    // --- 1. Search Alliances ---
    if (allNames && Object.keys(allNames).length > 0) {
        // Search alliance names
        for (const [nameLower, allianceId] of Object.entries(allNames)) {
            if (nameLower.includes(query)) {
                matchesMap.set(`alliance-${allianceId}`, {
                    name: nameLower,
                    id: allianceId,
                    matchType: 'name',
                    type: 'alliance'
                });
            }
        }

        // Search alliance tickers
        if (allTickers) {
            for (const [tickerLower, allianceId] of Object.entries(allTickers)) {
                if (tickerLower.includes(query)) {
                    const key = `alliance-${allianceId}`;
                    if (!matchesMap.has(key)) {
                        const nameLower = Object.entries(allNames).find(([n, id]) => id === allianceId)?.[0] || '';
                        matchesMap.set(key, {
                            name: nameLower,
                            id: allianceId,
                            matchType: 'ticker',
                            type: 'alliance'
                        });
                    }
                }
            }
        }
    }

    // --- 2. Search Corporations (Redis) ---
    if (multiMode && corpNames && Object.keys(corpNames).length > 0) {
        // Search corporation names
        for (const [nameLower, corpId] of Object.entries(corpNames)) {
            if (nameLower.includes(query)) {
                matchesMap.set(`corp-${corpId}`, {
                    name: nameLower,
                    id: corpId,
                    matchType: 'name',
                    type: 'corporation'
                });
            }
        }

        // Search corporation tickers
        if (corpTickers) {
            for (const [tickerLower, corpId] of Object.entries(corpTickers)) {
                if (tickerLower.includes(query)) {
                    const key = `corp-${corpId}`;
                    if (!matchesMap.has(key)) {
                        const nameLower = Object.entries(corpNames).find(([n, id]) => id === corpId)?.[0] || '';
                        matchesMap.set(key, {
                            name: nameLower,
                            id: corpId,
                            matchType: 'ticker',
                            type: 'corporation'
                        });
                    }
                }
            }
        }
    }

    let matches = Array.from(matchesMap.values());

    if (matches.length === 0) {
        if (multiMode) {
            return [{ json: { _isArray: true, results: [] } }];
        }
        return [{ json: { error: "Not found", query: query } }];
    }

    // Fetch activity scores for all matches (for sorting)
    const activityScores = new Map();
    for (const match of matches) {
        try {
            const statsKey = match.type === 'alliance' ? `${ALLIANCE_STATS_KEY}${match.id}` : `${CORP_STATS_KEY}${match.id}`;
            const stats = await redis.hmget(statsKey, 'kill_count_total', 'loss_count_total');
            const kills = parseInt(stats[0]) || 0;
            const losses = parseInt(stats[1]) || 0;
            activityScores.set(String(match.id), kills + losses);
        } catch (e) {
            activityScores.set(String(match.id), 0);
        }
    }

    // Sort by relevance
    matches.sort((a, b) => {
        // Exact match first
        if (a.name === query) return -1;
        if (b.name === query) return 1;

        // Starts with query second
        const aStarts = a.name.startsWith(query);
        const bStarts = b.name.startsWith(query);
        if (aStarts && !bStarts) return -1;
        if (bStarts && !aStarts) return 1;

        // Name match over ticker match
        if (a.matchType === 'name' && b.matchType === 'ticker') return -1;
        if (b.matchType === 'name' && a.matchType === 'ticker') return 1;

        // Activity score (higher is better)
        const aActivity = activityScores.get(String(a.id)) || 0;
        const bActivity = activityScores.get(String(b.id)) || 0;
        if (aActivity !== bActivity) return bActivity - aActivity;

        // Shorter name wins
        return a.name.length - b.name.length;
    });

    if (multiMode) {
        const results = [];
        const selectedMatches = matches.slice(0, 15);

        for (const match of selectedMatches) {
            const idToNameKey = match.type === 'alliance' ? ALLIANCE_ID_TO_NAME_KEY : CORP_ID_TO_NAME_KEY;
            const idToTickerKey = match.type === 'alliance' ? ALLIANCE_ID_TO_TICKER_KEY : CORP_ID_TO_TICKER_KEY;
            const tickerToIdKey = match.type === 'alliance' ? ALLIANCE_TICKER_TO_ID_KEY : CORP_TICKER_TO_ID_KEY;

            let properName = await redis.hget(idToNameKey, match.id) || match.name;
            let ticker = await redis.hget(idToTickerKey, match.id);

            results.push({
                id: parseInt(match.id),
                name: properName,
                ticker: ticker || null,
                type: match.type,
                _needsTicker: !ticker
            });
        }

        // Fetch missing tickers from ESI (limit to 5 to avoid rate limiting)
        const needTickers = results.filter(r => r._needsTicker).slice(0, 5);
        if (needTickers.length > 0) {
            const tickerPromises = needTickers.map(async (r) => {
                const ticker = await fetchTickerFromESI(r.id, r.type);
                if (ticker) {
                    r.ticker = ticker;
                    const idToTickerKey = r.type === 'alliance' ? ALLIANCE_ID_TO_TICKER_KEY : CORP_ID_TO_TICKER_KEY;
                    const tickerToIdKey = r.type === 'alliance' ? ALLIANCE_TICKER_TO_ID_KEY : CORP_TICKER_TO_ID_KEY;
                    await redis.hset(idToTickerKey, String(r.id), ticker);
                    await redis.hset(tickerToIdKey, ticker.toLowerCase(), String(r.id));
                }
            });
            await Promise.all(tickerPromises);
        }

        results.forEach(r => delete r._needsTicker);

        return [{ json: { _isArray: true, results: results } }];
    } else {
        // Single mode - return top match
        const topMatch = matches[0];
        const idToNameKey = topMatch.type === 'alliance' ? ALLIANCE_ID_TO_NAME_KEY : CORP_ID_TO_NAME_KEY;
        const idToTickerKey = topMatch.type === 'alliance' ? ALLIANCE_ID_TO_TICKER_KEY : CORP_ID_TO_TICKER_KEY;
        const tickerToIdKey = topMatch.type === 'alliance' ? ALLIANCE_TICKER_TO_ID_KEY : CORP_TICKER_TO_ID_KEY;

        const properName = await redis.hget(idToNameKey, topMatch.id);
        let ticker = await redis.hget(idToTickerKey, topMatch.id);

        if (!ticker) {
            ticker = await fetchTickerFromESI(topMatch.id, topMatch.type);
            if (ticker) {
                await redis.hset(idToTickerKey, String(topMatch.id), ticker);
                await redis.hset(tickerToIdKey, ticker.toLowerCase(), String(topMatch.id));
            }
        }

        return [{ json: {
            id: parseInt(topMatch.id),
            name: properName || topMatch.name,
            ticker: ticker || null,
            type: topMatch.type,
            matches_found: matches.length
        } }];
    }

} catch (e) {
    return [{ json: { error: e.message } }];
} finally {
    if (redis) redis.quit();
}
